  "inlineSchema": "// Prisma Schema for MID TRACK – SRKR Engineering College Mid Marks Management System\n// Relational Database Schema\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// 1. Users Table (Authentication & Identity)\nmodel User {\n  id           String   @id @default(uuid())\n  username     String   @unique // Faculty EMPID or Student Register Number\n  passwordHash String   @map(\"password_hash\")\n  role         String   @default(\"STUDENT\") // \"FACULTY\" or \"STUDENT\" (Strictly No Super Admin)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  // 1-to-1 Relations with Profile Tables\n  facultyProfile Faculty?\n  studentProfile Student?\n\n  @@map(\"users\")\n}\n\n// 2. Faculty Table\nmodel Faculty {\n  id         String   @id @default(uuid())\n  userId     String   @unique @map(\"user_id\")\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  facultyId  String   @unique @map(\"faculty_id\") // Unique EMPID assigned by SRKR (e.g. \"780\", \"781\")\n  name       String // Full Name (e.g., Dr. M SURESH BABU, Dr. N G K MURTHY)\n  department String? // Department/Branch (e.g. \"CSD\", \"CSIT\")\n  createdAt  DateTime @default(now()) @map(\"created_at\")\n  updatedAt  DateTime @updatedAt @map(\"updated_at\")\n\n  // Relations\n  marksEntered Mark[]\n\n  @@map(\"faculty\")\n}\n\n// 3. Students Table\nmodel Student {\n  id             String   @id @default(uuid())\n  userId         String   @unique @map(\"user_id\")\n  user           User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  registerNumber String   @unique @map(\"register_number\") // Unique Register No (e.g. \"24B91A0701\")\n  name           String // Full Student Name\n  branch         String // Branch (e.g., \"CSD\", \"CSIT\")\n  section        String // Section Name (e.g., \"CSD\", \"CSIT\", \"CSIT-A\", \"CSIT-B\")\n  academicYear   String   @map(\"academic_year\") // e.g. \"2025-2026\"\n  semester       Int // Semester (1 to 8, e.g. 2, 4, 6)\n  createdAt      DateTime @default(now()) @map(\"created_at\")\n  updatedAt      DateTime @updatedAt @map(\"updated_at\")\n\n  // Relations\n  marks Mark[]\n\n  @@index([branch, section, semester, academicYear])\n  @@map(\"students\")\n}\n\n// 4. Sections Table\nmodel Section {\n  id           String   @id @default(uuid())\n  sectionName  String   @map(\"section_name\") // e.g., \"CSD\", \"CSIT\", \"CSIT-A\", \"CSIT-B\"\n  branch       String // e.g., \"CSD\", \"CSIT\"\n  academicYear String   @map(\"academic_year\") // e.g., \"2025-2026\"\n  semester     Int // Semester (e.g. 2, 4, 6)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  // Relations\n  marks Mark[]\n\n  @@unique([sectionName, branch, academicYear, semester], name: \"section_composite_unique\")\n  @@map(\"sections\")\n}\n\n// 5. Subjects Table\nmodel Subject {\n  id          String   @id @default(uuid())\n  subjectCode String   @map(\"subject_code\") // e.g., \"CS301\", \"CS302\"\n  subjectName String   @map(\"subject_name\") // e.g., \"Computer Networks\", \"DBMS\"\n  branch      String // e.g., \"CSD\", \"CSIT\"\n  semester    Int // Semester (1 to 8)\n  createdAt   DateTime @default(now()) @map(\"created_at\")\n  updatedAt   DateTime @updatedAt @map(\"updated_at\")\n\n  // Relations\n  marks Mark[]\n\n  @@unique([subjectCode, branch, semester], name: \"subject_composite_unique\")\n  @@map(\"subjects\")\n}\n\n// 6. Exams Table\nmodel Exam {\n  id           String   @id @default(uuid())\n  examType     String   @map(\"exam_name\") // \"MID_1\" or \"MID_2\"\n  academicYear String   @map(\"academic_year\") // e.g., \"2025-2026\"\n  semester     Int // Semester (1 to 8)\n  createdAt    DateTime @default(now()) @map(\"created_at\")\n  updatedAt    DateTime @updatedAt @map(\"updated_at\")\n\n  // Relations\n  marks Mark[]\n\n  @@unique([examType, academicYear, semester], name: \"exam_composite_unique\")\n  @@map(\"exams\")\n}\n\n// 7. Marks Table (Question-wise Descriptive, Objective, Assignment & Grand Total)\nmodel Mark {\n  id        String  @id @default(uuid())\n  studentId String  @map(\"student_id\")\n  student   Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  facultyId String?  @map(\"faculty_id\")\n  faculty   Faculty? @relation(fields: [facultyId], references: [id], onDelete: SetNull)\n\n  subjectId String  @map(\"subject_id\")\n  subject   Subject @relation(fields: [subjectId], references: [id], onDelete: Cascade)\n\n  sectionId String  @map(\"section_id\")\n  section   Section @relation(fields: [sectionId], references: [id], onDelete: Cascade)\n\n  examId String @map(\"exam_id\")\n  exam   Exam   @relation(fields: [examId], references: [id], onDelete: Cascade)\n\n  // DESCRIPTIVE QUESTIONS (Choice pairs: Q1/Q2, Q3/Q4, Q5/Q6; Max 5 marks each)\n  descriptiveQ1OrQ2 Float? @default(0) @map(\"descriptive_q1_or_q2\")\n  descriptiveQ3OrQ4 Float? @default(0) @map(\"descriptive_q3_or_q4\")\n  descriptiveQ5OrQ6 Float? @default(0) @map(\"descriptive_q5_or_q6\")\n  descriptiveTotal  Float  @default(0) @map(\"descriptive_total\") // Max 15\n\n  // OBJECTIVE QUESTIONS (5 questions @ 2 marks each; Max 2 marks each)\n  objectiveQ1    Float? @default(0) @map(\"objective_q1\")\n  objectiveQ2    Float? @default(0) @map(\"objective_q2\")\n  objectiveQ3    Float? @default(0) @map(\"objective_q3\")\n  objectiveQ4    Float? @default(0) @map(\"objective_q4\")\n  objectiveQ5    Float? @default(0) @map(\"objective_q5\")\n  objectiveTotal Float  @default(0) @map(\"objective_total\") // Max 10\n\n  // CONTINUOUS EVALUATION ASSIGNMENT (Max 5 marks)\n  assignmentMarks Float @default(0) @map(\"assignment_marks\")\n\n  // GRAND TOTAL (Descriptive 15 + Objective 10 + Assignment 5 = Max 30)\n  total Float @default(0) @map(\"total\")\n\n  createdAt DateTime @default(now()) @map(\"created_at\")\n  updatedAt DateTime @updatedAt @map(\"updated_at\")\n\n  // Constraints: Exactly 1 record per student per subject per exam (allows updates without duplication)\n  @@unique([studentId, subjectId, examId], name: \"student_subject_exam_unique\")\n  @@index([sectionId, subjectId, examId])\n  @@map(\"marks\")\n}\n",
  "inlineSchemaHash": "b65e946581cbafad139cb48bc761644d538b24ef5761658001fe3bef8fa67915",
